-- NEXA schema v1. Migration owner only; application runs as nexa_app.
CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tenants(id text PRIMARY KEY, name text NOT NULL, is_demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), role text NOT NULL CHECK(role IN ('admin','manager','researcher','sales','compliance')), data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id));
CREATE TABLE industry_templates(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id));
CREATE TABLE icp_profiles(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), code text NOT NULL CHECK(code ~ '^H(0[1-9]|10)$'), data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,code));
CREATE TABLE source_policies(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), provider text NOT NULL, enabled boolean NOT NULL DEFAULT false, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,provider));
CREATE TABLE accounts(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), name text NOT NULL, province text NOT NULL CHECK(province IN ('QC','ON')), profile text NOT NULL CHECK(profile ~ '^H(0[1-9]|10)$'), is_demo boolean NOT NULL DEFAULT false, state text NOT NULL DEFAULT 'review' CHECK(state IN ('review','qualified','excluded')), data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id));
CREATE TABLE account_keys(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), account_id text NOT NULL, kind text NOT NULL CHECK(kind IN ('domain','registry','external')), value text NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,kind,value), FOREIGN KEY(tenant_id,account_id) REFERENCES accounts(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE contacts(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), account_id text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,account_id) REFERENCES accounts(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE partners(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), account_id text NOT NULL, state text NOT NULL DEFAULT 'application' CHECK(state IN ('application','review','approved','activated','rejected')), data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,account_id), FOREIGN KEY(tenant_id,account_id) REFERENCES accounts(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE projects(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), account_id text NOT NULL, state text NOT NULL DEFAULT 'unverified', data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,account_id) REFERENCES accounts(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE project_participants(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), project_id text NOT NULL, account_id text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,project_id) REFERENCES projects(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY(tenant_id,account_id) REFERENCES accounts(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE leads(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), account_id text NOT NULL, fit integer NOT NULL CHECK(fit BETWEEN 0 AND 100), intent integer NOT NULL CHECK(intent BETWEEN 0 AND 100), state text NOT NULL CHECK(state IN ('review','qualified','excluded')), data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,account_id), FOREIGN KEY(tenant_id,account_id) REFERENCES accounts(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE evidence(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), account_id text NOT NULL, source_url text NOT NULL CHECK(source_url LIKE 'https://%'), observed_at timestamptz NOT NULL, confidence numeric NOT NULL CHECK(confidence BETWEEN 0 AND 1), verification text NOT NULL CHECK(verification IN ('unverified','verified','rejected')), is_demo boolean NOT NULL DEFAULT false, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,account_id) REFERENCES accounts(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE credential_verifications(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), account_id text NOT NULL, province text NOT NULL CHECK(province IN ('QC','ON')), status text NOT NULL CHECK(status IN ('unknown','verified','invalid','not_required')), data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,account_id) REFERENCES accounts(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE search_jobs(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), status text NOT NULL CHECK(status IN ('queued','running','paused','completed','failed','budget_exhausted')), idempotency_key text NOT NULL, cursor integer NOT NULL DEFAULT 0, calls_used integer NOT NULL DEFAULT 0, lease_until timestamptz, next_attempt_at timestamptz, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,idempotency_key));
CREATE TABLE job_items(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), job_id text NOT NULL, ordinal integer NOT NULL, status text NOT NULL CHECK(status IN ('pending','done','failed')), data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,job_id,ordinal), FOREIGN KEY(tenant_id,job_id) REFERENCES search_jobs(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE source_attempts(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), job_id text NOT NULL, provider text NOT NULL, status text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,job_id) REFERENCES search_jobs(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE consent_records(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), account_id text NOT NULL, contact_id text NOT NULL, status text NOT NULL CHECK(status IN ('pending','approved','rejected','revoked')), data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,account_id) REFERENCES accounts(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY(tenant_id,contact_id) REFERENCES contacts(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE outreach_drafts(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), account_id text NOT NULL, contact_id text NOT NULL, status text NOT NULL CHECK(status IN ('draft','approved','rejected','blocked')), revision integer NOT NULL DEFAULT 1, language text NOT NULL CHECK(language IN ('fr','en')), data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,account_id) REFERENCES accounts(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY(tenant_id,contact_id) REFERENCES contacts(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE interactions(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), account_id text NOT NULL, external_id text NOT NULL, category text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,external_id), FOREIGN KEY(tenant_id,account_id) REFERENCES accounts(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE opportunities(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), account_id text NOT NULL, stage text NOT NULL CHECK(stage IN ('new','meeting','rfq','partner_review','won','lost')), data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,account_id) REFERENCES accounts(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE tasks(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), account_id text NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','done','cancelled')), data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,account_id) REFERENCES accounts(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE suppressions(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), account_id text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,account_id), FOREIGN KEY(tenant_id,account_id) REFERENCES accounts(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE audit_events(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id));
CREATE TABLE webhook_events(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), external_id text NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,external_id));
CREATE INDEX evidence_account ON evidence(tenant_id,account_id);
CREATE INDEX jobs_ready ON search_jobs(tenant_id,status,next_attempt_at,lease_until);
CREATE INDEX items_pending ON job_items(tenant_id,job_id,status,ordinal);
CREATE INDEX audit_time ON audit_events(tenant_id,created_at);
-- Both RLS and tenant-qualified FKs remain effective if application filters fail.
DO $$ DECLARE t text; BEGIN
 FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='public' AND tablename NOT IN ('tenants','schema_migrations') LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
  EXECUTE format('CREATE POLICY tenant_scope ON %I USING (tenant_id = nullif(current_setting(''app.tenant_id'',true),'''')) WITH CHECK (tenant_id = nullif(current_setting(''app.tenant_id'',true),''''))',t);
 END LOOP;
END $$;
ALTER TABLE tenants ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenants FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON tenants USING(id = nullif(current_setting('app.tenant_id',true),'')) WITH CHECK(id = nullif(current_setting('app.tenant_id',true),''));
CREATE OR REPLACE FUNCTION prevent_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'audit events are immutable'; END $$;
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION prevent_audit_mutation();
INSERT INTO schema_migrations(version) VALUES(1);
